    "id": "claudinite-website/no-conflict-markers",
    "severity": "blocking",
    "failureMessage": "A conflict marker left behind breaks the file, and in a rules or config file it silently changes what the repo instructs every later session and check to do.",
    "scanFiles": "/.*/",
    "matchLines": [
      {
        "match": "/^(<{7}|\\|{7}|>{7}) \\S/",
        "what": "a merge-conflict marker line survives here",
        "fix": "Finish the resolution, delete the marker line, then re-read the whole file before staging — never chain the grep that checks for markers with the command that stages."
      }
    ]
  }
]

// This repo's own pack: conventions for the claudinite.com marketing site and
// for maintaining this repo's Claudinite mount. Prose + one bundled skill, no
// structural fingerprint of its own — the declaration in .claudinite-checks.json
// is authoritative (detect: null skips the drift check in both directions).
import nodeTestDiscovery from './node-test-discovery.mjs';
import siteVersionTooltip from './site-version-tooltip.mjs';

export default {
  id: 'claudinite-website',
  ruleRoutingGuidance: {
    belongs: "conventions for the claudinite.com marketing site and for maintaining this repo's Claudinite mount",
    excludes: 'general site markup and product research — those are html and product-wiki',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [nodeTestDiscovery, siteVersionTooltip],
  skills: ['site-visual-check'],
};

